import sympy as sp

def check_squares(c, d, e, x_range=(-100, 100)):
    x = sp.Symbol('x')
    Q = x**3 + c*x**2 + d*x + e

    solutions = []
    for val in range(x_range[0], x_range[1] + 1):
        res = Q.subs(x, val)
        if res >= 0:
            root = int(res**0.5)
            if root * root == res:
                solutions.append(val)
    return solutions

