    # e must be a square for Q(0) to be a square
    root_e = int(abs(e)**0.5)
    if root_e * root_e != abs(e) or e < 0:
        continue

    for c in range(-10, 11):
        for d in range(-10, 11):
            # Q(1) must be a square
            q1 = 1 + c + d + e
            if q1 < 0:
                continue
            root_q1 = int(q1**0.5)
            if root_q1 * root_q1 != q1:
                continue

            # Now check if only x=0, 1 are solutions
            sols = check_squares(c, d, e)
            if sols == [0, 1]:
                found.append((c, d, e, q1))

