def check_large_range(c, d, e, x_min, x_max):
    for x in range(x_min, x_max + 1):
        val = x**3 + c*x**2 + d*x + e
        if val >= 0:
            root = int(val**0.5)
            if root * root == val:
                if x != 0 and x != 1:
                    return x
    return None

